import{_ as a,o as t,c as r,ag as o}from"./chunks/framework.cyF4XceO.js";const h=JSON.parse('{"title":"Pull Queue Family proposals","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/queue/index.md","filePath":"proposals/queue/index.md"}'),i={name:"proposals/queue/index.md"};function s(n,e,l,d,c,u){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="pull-queue-family-proposals" tabindex="-1">Pull Queue Family proposals <a class="header-anchor" href="#pull-queue-family-proposals" aria-label="Permalink to &quot;Pull Queue Family proposals&quot;">​</a></h1><p>The Pull Queue Family, <code>queue.forms.takoform.com/v1beta1</code>, is minted under <a href="./../../spec/decisions/0043-forms-target-popular-vendor-locked-primitives.html">decision 0043</a>: the pull queue is popularly offered as a managed service by every major provider and has no de-facto standard API, so a host-neutral contract is the only portability there is. Its members fix, completely, the application-visible semantics of the proven visibility-timeout pull queue shape without naming its vendor (<a href="./../../spec/decisions/0008-forms-preserve-service-shape.html">decision 0008</a>).</p><h2 id="authoring-policy-shape-preserving-contracts" tabindex="-1">Authoring policy: shape-preserving contracts <a class="header-anchor" href="#authoring-policy-shape-preserving-contracts" aria-label="Permalink to &quot;Authoring policy: shape-preserving contracts&quot;">​</a></h2><p>Every member Form preserves one service shape end to end: client API, data model, delivery guarantees, update and delete units, error semantics, and the capabilities exposed through typed Bindings. No free semantic token is admitted; a difference in semantics is a different Form, never a selector value. Outward capability use is a digest-bound Binding held by a revision resource; inward activation is an attachment resource (<a href="./../../spec/decisions/0010-exact-interface-and-binding-contracts.html">decision 0010</a>). Desired schemas carry no <code>name</code> or envelope plumbing: the resource envelope owns identity and status (<a href="./../../spec/decisions/0011-resource-identity-generation-and-revision.html">decision 0011</a>).</p><p>No catalog source, generated candidate set, Interface candidate, or Binding candidate exists for this family yet. A Form exists only when its proposal, catalog declaration, and candidate package exist (<a href="./../">proposals/README.md</a>); these documents reserve nothing.</p><h2 id="mvp-members" tabindex="-1">MVP members <a class="header-anchor" href="#mvp-members" aria-label="Permalink to &quot;MVP members&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Form</th><th>Role</th><th>One-line semantics</th><th>Separate-Form boundary</th></tr></thead><tbody><tr><td><a href="./pull-queue.html">PullQueue</a></td><td>identity</td><td>Unordered at-least-once queue drained by consumers calling receive, with visibility timeout, receive counting, dead-lettering, and long polling.</td><td>A FIFO or exactly-once queue, or push delivery into a worker handler, is a different Form.</td></tr></tbody></table><h2 id="two-queue-forms-deliberately" tabindex="-1">Two queue Forms, deliberately <a class="header-anchor" href="#two-queue-forms-deliberately" aria-label="Permalink to &quot;Two queue Forms, deliberately&quot;">​</a></h2><p>The Edge Platform Family&#39;s <a href="./../edge/at-least-once-queue.html">AtLeastOnceQueue</a> is not this Form. There the host pushes batches into a worker&#39;s <code>queue</code> handler and settlement is per-batch; here consumers pull messages through an API and settle each one by deleting it under a visibility timeout. Decision 0043 records why both exist: two proven shapes, two contracts, per decision 0008. A <code>FifoQueue</code> or a per-message-HTTP-target task queue would likewise be separate Forms with their own proposals, per <a href="./../../spec/form-families.html">spec/form-families.md</a>.</p>',9)])])}const m=a(i,[["render",s]]);export{h as __pageData,m as default};
